import{_ as e,o as t,c as o,a2 as s}from"./chunks/framework.vLhlLNVn.js";const i="/assets/compilednewdevice.BWBzbX3x.png",n="/assets/tasmota_main.A0vlOJ4H.png",r="/assets/tasmota_ota.BjYXOMGu.png",d="/assets/tasmota_upload.dMabUQna.png",l="/assets/espeasy_ota.DyrQ82D1.png",_=JSON.parse('{"title":"Tasmota / ESPEasy migration","description":"","frontmatter":{"order":6},"headers":[],"relativePath":"adapter/esphome/migration.md","filePath":"adapter/esphome/migration.md","lastUpdated":1794650433000}'),c={name:"adapter/esphome/migration.md"};function p(h,a,m,u,y,g){return t(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="tasmota-espeasy-migration" tabindex="-1">Tasmota / ESPEasy migration <a class="header-anchor" href="#tasmota-espeasy-migration" aria-label="Permalink to &quot;Tasmota / ESPEasy migration&quot;">​</a></h1><p>Migrating from previous Sonoff Tasmota or ESPEasy setups is very easy. You just need to have ESPHome create a binary for you and then upload that in the web interface.</p><h2 id="download-binary" tabindex="-1">Download Binary <a class="header-anchor" href="#download-binary" aria-label="Permalink to &quot;Download Binary&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>First follow the guides <a href="./myfirstdevice">My First Device</a> and create a configuration file. Then, generate and download the binary:</p></div><img src="'+i+'" width="60%" height="60%" align="center"><h2 id="upload-binary" tabindex="-1">Upload Binary <a class="header-anchor" href="#upload-binary" aria-label="Permalink to &quot;Upload Binary&quot;">​</a></h2><p>To upload the binary, navigate to the Tasmota/ESPEasy web interface</p><h2 id="tasmota" tabindex="-1">Tasmota <a class="header-anchor" href="#tasmota" aria-label="Permalink to &quot;Tasmota&quot;">​</a></h2><p>Enter the &quot;Firmware Upgrade&quot; section.</p><img src="'+n+'" width="60%" height="60%" align="center"><p>In the &quot;Upgrade by file upload&quot; section, choose the binary you previously downloaded</p><img src="'+r+'" width="60%" height="60%" align="center"><p>If everything succeeds, you will see an &quot;Upload Successful&quot; message and ESPHome will connect to the WiFi network configured in your .yaml file. 🎉</p><img src="'+d+'" width="60%" height="60%" align="center"><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>When using the <code>esp8266_pwm output &lt;/components/output/esp8266_pwm&gt;</code> platform and switching from Tasmota, you need to power-cycle the device once. After that the dimming functionality will work as usual and no more power cycles are required.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you are using Tasmota 8+ and get an error after uploading the firmware, go to the console and type <code>SetOption78 1</code>, then restart the device and try the firmware again.</p></div><h3 id="espeasy" tabindex="-1">ESPEasy <a class="header-anchor" href="#espeasy" aria-label="Permalink to &quot;ESPEasy&quot;">​</a></h3><p>Enter the &quot;Tools &quot; section.</p><img src="'+l+'" width="60%" height="60%"><p>Press &quot;Load&quot; under Firmware, then select the binary you previously downloaded and upload the binary. If everything succeeds, you should now have ESPHome on your node 🎉.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>with ESPHome, you in most cases won&#39;t need to worry about the available flash size, as the binary only ever includes the code that you are actually using.</p></div>',21)])])}const b=e(c,[["render",p]]);export{_ as __pageData,b as default};
